// Devolve para a IA somente dados operacionais.
// A mensagem ao cliente ja foi enviada por este subworkflow apos sucesso da transferencia.
const especificaExecutada = $('Solicitar transferencia especifica ao CRM').isExecuted;
const transferencia = especificaExecutada
  ? $('Solicitar transferencia especifica ao CRM').first().json
  : $('Solicitar proximo humano ao CRM').first().json;
const entrada = $('When Executed by Another Workflow').first().json;
const confirmacao = $('Enviar confirmacao de transferencia pela Meta').first().json;
const registro = $('Registrar confirmacao de transferencia no CRM').first().json;
const lembreteCriado = $('Criar lembrete retorno expediente no CRM').isExecuted;
const lembrete = lembreteCriado ? $('Criar lembrete retorno expediente no CRM').first().json : {};
const preparoLembrete = $('Preparar lembrete retorno expediente').isExecuted
  ? $('Preparar lembrete retorno expediente').first().json
  : {};

return [{ json: {
  sucesso: true,
  codigo: 'CLIENTE_TRANSFERIDO',
  atendimento_id: String(transferencia.atendimentoId ?? entrada.atendimento_id),
  atendente_id: String(transferencia.atendenteId ?? entrada.atendente_id ?? ''),
  atendente_nome: String($('Preparar confirmacao de transferencia').first().json.atendente_nome ?? ''),
  status: String(transferencia.status ?? ''),
  transferir_para_atendente_especifico: Boolean(entrada.transferir_para_atendente_especifico),
  fora_horario_humano: Boolean(entrada.fora_horario_humano),
  mensagem_cliente_enviada: true,
  texto_enviado_ao_cliente: String($('Preparar confirmacao de transferencia').first().json.texto ?? ''),
  whatsapp_message_id: String(confirmacao.messages?.[0]?.id ?? ''),
  mensagem_crm_id: String(registro.mensagemId ?? ''),
  lembrete_retorno_expediente_criado: lembreteCriado,
  lembrete_retorno_expediente_id: String(lembrete.id ?? lembrete.lembreteId ?? ''),
  lembrete_retorno_expediente_data_hora: String(preparoLembrete.dataHora ?? '')
} }];

// Calcula o lembrete RF-AUT-07 a partir do horario cadastrado na FAQ.
// Regra: agendar para 5 minutos depois do proximo inicio de expediente disponivel.
const entrada = $('When Executed by Another Workflow').first().json;
const textos = $('Textos da transferencia').first().json;
const timezone = String(textos.timezone ?? '').trim();
const minutosLembrete = Number(textos.minutos_lembrete_pos_inicio_expediente);
if (!timezone) throw new Error('TIMEZONE_TRANSFERENCIA_NAO_CONFIGURADO');
if (!Number.isFinite(minutosLembrete) || minutosLembrete < 0) throw new Error('MINUTOS_LEMBRETE_TRANSFERENCIA_INVALIDO');
const horarioFaq = $('Consultar horario expediente na FAQ').first().json;
const respostaHorario = String(horarioFaq.resposta ?? '').trim();

if (!respostaHorario) {
  throw new Error('FAQ_HORARIO_EXPEDIENTE_NAO_CADASTRADA');
}

const normalizar = (texto) => String(texto ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase();

const extrairInicio = (trecho) => {
  const match = String(trecho).match(/(\d{1,2})(?::|h)?(\d{2})?/);
  if (!match) return null;
  return {
    hora: Number(match[1]),
    minuto: Number(match[2] ?? 0)
  };
};

const regrasPorDia = new Map();
for (const parte of respostaHorario.split(',')) {
  const texto = normalizar(parte);
  const inicio = extrairInicio(parte);
  if (!inicio) continue;

  if (texto.includes('segunda') && texto.includes('sexta')) {
    for (const dia of [1, 2, 3, 4, 5]) regrasPorDia.set(dia, inicio);
  } else if (texto.includes('sabado')) {
    regrasPorDia.set(6, inicio);
  } else if (texto.includes('domingo')) {
    regrasPorDia.set(0, inicio);
  }
}

if (regrasPorDia.size === 0) {
  throw new Error('FAQ_HORARIO_EXPEDIENTE_SEM_INICIO_RECONHECIVEL');
}

const partesSP = (data) => {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    weekday: 'short',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23'
  }).formatToParts(data).reduce((acc, parte) => {
    acc[parte.type] = parte.value;
    return acc;
  }, {});

  const diaSemana = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 }[partes.weekday];
  return {
    ano: Number(partes.year),
    mes: Number(partes.month),
    dia: Number(partes.day),
    hora: Number(partes.hour),
    minuto: Number(partes.minute),
    segundo: Number(partes.second),
    diaSemana
  };
};

const criarDataSP = ({ ano, mes, dia }, hora, minuto) => {
  // Converte o horario local de Sao Paulo para ISO UTC sem fixar offset manualmente.
  const alvoComoUtc = Date.UTC(ano, mes - 1, dia, hora, minuto, 0);
  let candidato = new Date(alvoComoUtc);

  for (let tentativa = 0; tentativa < 3; tentativa++) {
    const local = partesSP(candidato);
    const localComoUtc = Date.UTC(local.ano, local.mes - 1, local.dia, local.hora, local.minuto, local.segundo);
    const diferenca = localComoUtc - alvoComoUtc;
    const ajustado = new Date(candidato.getTime() - diferenca);
    if (Math.abs(ajustado.getTime() - candidato.getTime()) < 1000) return ajustado;
    candidato = ajustado;
  }

  return candidato;
};

const somarDiasLocais = (base, dias) => {
  const referenciaUtcMeioDia = new Date(Date.UTC(base.ano, base.mes - 1, base.dia + dias, 15, 0, 0));
  return partesSP(referenciaUtcMeioDia);
};

const agora = new Date();
const hojeSP = partesSP(agora);
let dataHora = null;

for (let deslocamento = 0; deslocamento < 14; deslocamento++) {
  const diaCandidato = somarDiasLocais(hojeSP, deslocamento);
  const inicio = regrasPorDia.get(diaCandidato.diaSemana);
  if (!inicio) continue;

  const minutoComLembrete = inicio.minuto + minutosLembrete;
  const candidato = criarDataSP(
    diaCandidato,
    inicio.hora + Math.floor(minutoComLembrete / 60),
    minutoComLembrete % 60
  );

  if (candidato > agora) {
    dataHora = candidato;
    break;
  }
}

if (!dataHora) {
  throw new Error('NAO_FOI_POSSIVEL_CALCULAR_LEMBRETE_RETORNO_EXPEDIENTE');
}

const atendimentoId = String(entrada.atendimento_id ?? '').trim();
const mensagemId = String(entrada.mensagem_id ?? 'sem-mensagem').trim() || 'sem-mensagem';
const leadNome = String(entrada.lead_nome ?? '').trim();
const templateLembrete = String(textos.texto_lembrete_retorno_expediente ?? '').trim();
if (!templateLembrete) throw new Error('TEXTO_LEMBRETE_TRANSFERENCIA_NAO_CONFIGURADO');
const textoLembrete = templateLembrete
  .replace(/\{nome\}/gi, leadNome || String(textos.nome_lead_fallback_lembrete ?? ''))
  .replace(/\s+/g, ' ')
  .trim();
if (!atendimentoId) throw new Error('ATENDIMENTO_ID_AUSENTE_PARA_LEMBRETE');

return [{ json: {
  atendimento_id: atendimentoId,
  texto: textoLembrete,
  dataHora: dataHora.toISOString(),
  idempotency_key: String(textos.idempotency_lembrete_prefixo ?? '') + ':' + atendimentoId + ':' + mensagemId,
  horario_faq_usado: respostaHorario
} }];

// Monta a mensagem sistematica de transferencia depois do sucesso real do CRM.
// O nome e o status vêm primeiro do retorno do CRM; se nao vierem, usamos a lista objetiva enviada pelo EV-01.
const entrada = $('When Executed by Another Workflow').first().json;
const textos = $('Textos da transferencia').first().json;
const especificaExecutada = $('Solicitar transferencia especifica ao CRM').isExecuted;
const transferencia = especificaExecutada
  ? $('Solicitar transferencia especifica ao CRM').first().json
  : $('Solicitar proximo humano ao CRM').first().json;

let atendentes = [];
try {
  const bruto = String(entrada.atendentes_transferiveis_json ?? '').trim();
  atendentes = bruto ? JSON.parse(bruto) : [];
} catch (error) {
  atendentes = [];
}

const atendenteId = String(transferencia.atendenteId ?? entrada.atendente_id ?? '');
const atendenteDaLista = atendentes.find((item) => String(item.atendente_id ?? item.id ?? '') === atendenteId);
const atendenteNome = String(
  transferencia.atendenteNome ??
  transferencia.atendente?.nome ??
  atendenteDaLista?.nome ??
  ''
).trim();

const statusBruto = String(
  transferencia.atendenteStatus ??
  transferencia.atendente?.status ??
  atendenteDaLista?.status ??
  ''
).trim().toLowerCase();
const disponivelAgora = transferencia.atendenteDisponivelAgora ??
  transferencia.atendente?.disponivelAgora ??
  transferencia.atendente?.disponivel_agora ??
  atendenteDaLista?.disponivel_agora ??
  atendenteDaLista?.disponivelAgora ??
  null;
const atendenteOffline = statusBruto === 'offline' || disponivelAgora === false;

const aplicarTemplate = (template, valores) => String(template ?? '')
  .replace(/{atendente}/gi, valores.atendente || '')
  .replace(/\s+/g, ' ')
  .trim();
const templateEspecifico = atendenteOffline
  ? textos.texto_confirmacao_transferencia_especifica_offline
  : textos.texto_confirmacao_transferencia_especifica;
const texto = atendenteNome
  ? aplicarTemplate(templateEspecifico, { atendente: atendenteNome })
  : aplicarTemplate(textos.texto_confirmacao_transferencia_generica, {});

if (!entrada.wa_id) throw new Error('WA_ID_AUSENTE_PARA_CONFIRMACAO_TRANSFERENCIA');
if (!entrada.phone_number_id) throw new Error('PHONE_NUMBER_ID_AUSENTE_PARA_CONFIRMACAO_TRANSFERENCIA');
if (!texto) throw new Error('TEXTO_CONFIRMACAO_TRANSFERENCIA_NAO_CONFIGURADO');

return [{ json: {
  atendimento_id: String(transferencia.atendimentoId ?? entrada.atendimento_id ?? ''),
  atendente_id: atendenteId,
  atendente_nome: atendenteNome,
  atendente_offline: atendenteOffline,
  wa_id: String(entrada.wa_id),
  phone_number_id: String(entrada.phone_number_id),
  texto
} }];

// Decide se a solicitacao deve virar transferencia real ou lista de atendentes.
// No modo padrao, preserva o comportamento antigo.
// No modo lista, dentro do expediente so transfere para atendente online.
const entrada = $('When Executed by Another Workflow').first().json;

let atendentes = [];
try {
  const bruto = String(entrada.atendentes_transferiveis_json ?? '').trim();
  atendentes = bruto ? JSON.parse(bruto) : [];
} catch (error) {
  atendentes = [];
}

const usarLista = entrada.usar_lista_atendentes === true;
let pediuEspecifico = entrada.transferir_para_atendente_especifico === true;
const foraHorario = entrada.fora_horario_humano === true;
// Recebido como fato calculado pelo EV-01. Não depende da IA obedecer ao prompt.
const bloquearGenericaForaHorarioComMemoria =
  entrada.bloquear_transferencia_generica_fora_horario_com_memoria === true;
let atendenteId = String(entrada.atendente_id ?? '').trim();
const textos = $('Textos da transferencia').first().json;
const pediuOutros = atendenteId === String(textos.lista_outros_row_id ?? '') ||
  atendenteId === String(textos.atendente_outros_id ?? '');
if (pediuOutros) {
  atendenteId = String(textos.atendente_outros_id ?? '').trim();
  pediuEspecifico = true;
}

const normalizar = (texto) => String(texto ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toLowerCase();

const estaOnline = (atendente) => {
  const status = normalizar(atendente?.status);
  return atendente?.disponivel_agora === true ||
    atendente?.disponivelAgora === true ||
    status === 'online' ||
    status === 'disponivel';
};

// A lista recebida e a fonte de verdade. Ela contem somente usuarios ativos liberados para IA; atendentes e subgestores podem ser selecionados com seguranca.
const atendenteSolicitado = atendenteId
  ? atendentes.find((item) => String(item.atendente_id ?? item.id ?? '') === atendenteId)
  : null;
const deduplicarAtendentes = (lista) => {
  const vistos = new Set();
  const unicos = [];
  for (const atendente of lista) {
    const id = String(atendente?.atendente_id ?? atendente?.id ?? '').trim();
    if (!id || vistos.has(id)) continue;
    vistos.add(id);
    unicos.push(atendente);
  }
  return unicos;
};

const atendentesOnline = deduplicarAtendentes(atendentes.filter(estaOnline));

let acao = pediuEspecifico ? 'TRANSFERIR_ESPECIFICA' : 'TRANSFERIR_PROXIMO';
let motivo = usarLista ? 'MODO_LISTA' : 'MODO_PADRAO';

if (bloquearGenericaForaHorarioComMemoria && !pediuEspecifico) {
  // Histórico existente + fora do horário: não transferir/listar automaticamente.
  // O EV-03 enviará somente o aviso pedindo o nome do atendente anterior.
  acao = 'ENVIAR_AVISO_FORA_HORARIO_COM_HISTORICO';
  motivo = 'FORA_HORARIO_COM_HISTORICO_SEM_TRANSFERENCIA_GENERICA';
} else if (usarLista) {
  if (!pediuEspecifico) {
    acao = 'ENVIAR_LISTA';
    motivo = 'SEM_ATENDENTE_ESPECIFICO_NO_MODO_LISTA';
  } else if (!atendenteSolicitado) {
    acao = 'ENVIAR_LISTA';
    motivo = 'ATENDENTE_ESPECIFICO_NAO_ENCONTRADO_NO_MODO_LISTA';
  } else if (estaOnline(atendenteSolicitado)) {
    acao = 'TRANSFERIR_ESPECIFICA';
    motivo = 'ATENDENTE_ESPECIFICO_ONLINE';
  } else if (foraHorario) {
    acao = 'TRANSFERIR_ESPECIFICA';
    motivo = 'ATENDENTE_ESPECIFICO_OFFLINE_FORA_DO_HORARIO';
  } else {
    acao = 'ENVIAR_LISTA';
    motivo = 'ATENDENTE_ESPECIFICO_OFFLINE_DENTRO_DO_HORARIO';
  }
}

return [{ json: {
  acao_transferencia: acao,
  motivo_acao_transferencia: motivo,
  usar_lista_atendentes: usarLista,
  fora_horario_humano: foraHorario,
  bloquear_transferencia_generica_fora_horario_com_memoria: bloquearGenericaForaHorarioComMemoria,
  transferir_para_atendente_especifico: pediuEspecifico,
  atendente_solicitado_id: atendenteId,
  atendente_solicitado_nome: String(atendenteSolicitado?.nome ?? ''),
  atendente_solicitado_online: atendenteSolicitado ? estaOnline(atendenteSolicitado) : false,
  atendentes_online_json: JSON.stringify(atendentesOnline),
  quantidade_atendentes_online: atendentesOnline.length
} }];

// Monta a lista interativa da Meta com atendentes online.
// Se nao houver atendentes online, envia um texto simples explicando a indisponibilidade.
const entrada = $('When Executed by Another Workflow').first().json;
const decisao = $('Definir acao transferencia').first().json;
const textos = $('Textos da transferencia').first().json;

let atendentesOnline = [];
try {
  const bruto = String(decisao.atendentes_online_json ?? '').trim();
  atendentesOnline = bruto ? JSON.parse(bruto) : [];
} catch (error) {
  atendentesOnline = [];
}

// Defesa em profundidade: o node anterior já envia apenas online, mas esta
// lista ainda confirma o estado recebido antes de criar qualquer botão.
const estaOnline = (atendente) => {
  const status = String(atendente?.status ?? '').trim().toLowerCase();
  return atendente?.disponivel_agora === true ||
    atendente?.disponivelAgora === true ||
    status === 'online' ||
    status === 'disponivel';
};
atendentesOnline = atendentesOnline.filter(estaOnline);

const maxItens = Math.min(Math.max(Number(textos.lista_atendentes_max_itens ?? 10), 1), 10);
const prefixo = String(textos.lista_atendentes_row_id_prefixo ?? '').trim();
const botao = String(textos.lista_atendentes_botao ?? '').trim();
const secao = String(textos.lista_atendentes_secao ?? '').trim();
// Outros aponta exclusivamente para Michele e somente aparece se ela estiver online.
const idOutrosPreferencial = String(textos.atendente_outros_id ?? '').trim();
if (!prefixo) throw new Error('PREFIXO_LISTA_ATENDENTES_NAO_CONFIGURADO');
if (!botao) throw new Error('BOTAO_LISTA_ATENDENTES_NAO_CONFIGURADO');
if (!secao) throw new Error('SECAO_LISTA_ATENDENTES_NAO_CONFIGURADA');

const cortar = (texto, limite) => {
  const valor = String(texto ?? '').replace(/\s+/g, ' ').trim();
  return valor.length > limite ? valor.slice(0, limite - 1).trimEnd() + '...' : valor;
};
const aplicarTemplate = (template) => String(template ?? '')
  .replace(/{atendente}/gi, decisao.atendente_solicitado_nome || 'esse atendente')
  .replace(/\s+/g, ' ')
  .trim();

const apenasAvisoForaHorarioComHistorico =
  decisao.acao_transferencia === 'ENVIAR_AVISO_FORA_HORARIO_COM_HISTORICO';
const texto = apenasAvisoForaHorarioComHistorico
  ? String(textos.texto_fora_horario_com_memoria ?? '').replace(/\s+/g, ' ').trim()
  : (decisao.motivo_acao_transferencia === 'ATENDENTE_ESPECIFICO_OFFLINE_DENTRO_DO_HORARIO'
    ? aplicarTemplate(textos.texto_lista_atendente_indisponivel)
    : aplicarTemplate(textos.texto_lista_atendentes_generica));

// A lista recebida e a fonte de verdade: contem somente usuarios ativos liberados para IA.
// Este node separa a apresentacao: ATENDENTE aparece por nome e Michele
// e representada pelo unico botao Outros.
const papelDoAtendente = (atendente) => String(atendente?.papel ?? '').trim().toUpperCase();
const idDoAtendente = (atendente) => String(atendente?.atendente_id ?? atendente?.id ?? '').trim();
// Outros e exclusivo da Michele. Um subgestor diferente jamais vira
// contingencia automatica, mesmo que esteja online no CRM.
const destinoOutros = atendentesOnline.find((atendente) =>
  papelDoAtendente(atendente) === 'SUBGESTOR' &&
  idDoAtendente(atendente) === idOutrosPreferencial
) ?? null;

const vistos = new Set();
const atendentesListados = [];
for (const atendente of atendentesOnline) {
  const id = idDoAtendente(atendente);
  const nome = String(atendente.nome ?? '').trim();
  // Um subgestor nunca aparece por nome; ele e o destino do botao Outros.
  if (!id || !nome || papelDoAtendente(atendente) !== 'ATENDENTE' || vistos.has(id)) continue;
  vistos.add(id);
  atendentesListados.push({ id, nome });
  if (atendentesListados.length >= maxItens) break;
}

const limiteRegulares = destinoOutros ? Math.max(maxItens - 1, 0) : maxItens;
const rows = atendentesListados.slice(0, limiteRegulares).map((atendente) => ({
  id: prefixo + atendente.id,
  title: cortar(atendente.nome, 24),
  description: String(textos.lista_atendentes_descricao_disponivel ?? '').trim()
}));

if (!apenasAvisoForaHorarioComHistorico && destinoOutros && rows.length < maxItens) {
  rows.push({
    id: prefixo + idDoAtendente(destinoOutros),
    title: String(textos.lista_outros_titulo ?? 'Outros'),
    description: 'Falar com outro atendente'
  });
}

if (!entrada.wa_id) throw new Error('WA_ID_AUSENTE_PARA_LISTA_ATENDENTES');
if (!entrada.phone_number_id) throw new Error('PHONE_NUMBER_ID_AUSENTE_PARA_LISTA_ATENDENTES');

// No aviso obrigatório não criamos botões; o cliente precisa informar o nome.
if (apenasAvisoForaHorarioComHistorico) rows.length = 0;
const listaEnviada = rows.length > 0;
const textoFinal = apenasAvisoForaHorarioComHistorico
  ? texto
  : (listaEnviada
    ? texto
    : String(textos.texto_lista_sem_atendentes_disponiveis ?? '').replace(/\s+/g, ' ').trim());
if (!textoFinal) throw new Error('TEXTO_LISTA_ATENDENTES_NAO_CONFIGURADO');

const payloadMeta = listaEnviada
  ? {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: String(entrada.wa_id),
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: textoFinal },
      action: {
        button: cortar(botao, 20),
        sections: [{ title: cortar(secao, 24), rows }]
      }
    }
  }
  : {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: String(entrada.wa_id),
    type: 'text',
    text: { preview_url: false, body: textoFinal }
  };

return [{ json: {
  atendimento_id: String(entrada.atendimento_id ?? ''),
  wa_id: String(entrada.wa_id),
  phone_number_id: String(entrada.phone_number_id),
  texto: textoFinal,
  lista_enviada: listaEnviada,
  apenas_aviso_fora_horario_com_historico: apenasAvisoForaHorarioComHistorico,
  atendentes_listados: atendentesListados,
  destino_outros_id: destinoOutros ? idDoAtendente(destinoOutros) : '',
  destino_outros_nome: destinoOutros ? String(destinoOutros.nome ?? '') : '',
  payload_meta: payloadMeta
} }];

// Retorna para o agente que este subworkflow ja enviou a lista ou o aviso ao cliente.
// O EV-01 deve usar esse codigo para nao mandar uma segunda mensagem.
const lista = $('Preparar lista de atendentes disponiveis').first().json;
const meta = $('Enviar lista de atendentes pela Meta').first().json;
const registro = $('Registrar lista de atendentes no CRM').first().json;

return [{ json: {
  sucesso: true,
  codigo: lista.apenas_aviso_fora_horario_com_historico ? 'AVISO_FORA_HORARIO_COM_HISTORICO_ENVIADO' : (lista.lista_enviada ? 'LISTA_ATENDENTES_ENVIADA' : 'LISTA_ATENDENTES_INDISPONIVEIS_ENVIADA'),
  atendimento_id: String(lista.atendimento_id ?? ''),
  transferencia_realizada: false,
  mensagem_cliente_enviada: true,
  texto_enviado_ao_cliente: String(lista.texto ?? ''),
  atendentes_listados: lista.atendentes_listados ?? [],
  whatsapp_message_id: String(meta.messages?.[0]?.id ?? ''),
  mensagem_crm_id: String(registro.mensagemId ?? '')
} }];
